CREATE TABLE workspaces (id TEXT PRIMARY KEY, payload TEXT NOT NULL CHECK(json_valid(payload)));
INSERT INTO workspaces VALUES ('my-learning', '{"id":"my-learning","name":"My Learning","description":"","goal":"","icon":"✦","accent":"violet","pinned":false,"archived":false,"createdAt":"2026-01-01T00:00:00.000Z","updatedAt":"2026-01-01T00:00:00.000Z","lastOpenedAt":"2026-01-01T00:00:00.000Z"}');
ALTER TABLE courses ADD COLUMN workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE;
UPDATE courses SET workspace_id='my-learning';
CREATE TRIGGER course_workspace_insert BEFORE INSERT ON courses WHEN new.workspace_id IS NULL BEGIN SELECT RAISE(ABORT,'Course needs a workspace'); END;
CREATE TRIGGER course_workspace_update BEFORE UPDATE OF workspace_id ON courses WHEN new.workspace_id IS NULL BEGIN SELECT RAISE(ABORT,'Course needs a workspace'); END;
CREATE UNIQUE INDEX courses_workspace_identity ON courses(id,workspace_id);
CREATE INDEX courses_workspace ON courses(workspace_id);
UPDATE courses SET payload=json_set(payload,'$.workspaceId','my-learning','$.subjectKind',CASE WHEN lower(json_extract(payload,'$.targetLanguage')) IN ('english','korean') THEN 'language' ELSE 'general' END);
CREATE TABLE app_metadata (id INTEGER PRIMARY KEY CHECK(id=1), active_workspace_id TEXT NOT NULL REFERENCES workspaces(id));
INSERT INTO app_metadata VALUES(1,'my-learning');
CREATE TABLE libraries (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, payload TEXT NOT NULL CHECK(json_valid(payload)), UNIQUE(id,workspace_id));
CREATE INDEX libraries_workspace ON libraries(workspace_id);
CREATE TABLE sources (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, payload TEXT NOT NULL CHECK(json_valid(payload)), UNIQUE(id,workspace_id));
CREATE INDEX sources_workspace ON sources(workspace_id);
CREATE TABLE source_libraries (source_id TEXT NOT NULL, library_id TEXT NOT NULL, workspace_id TEXT NOT NULL, PRIMARY KEY(source_id,library_id), FOREIGN KEY(source_id,workspace_id) REFERENCES sources(id,workspace_id) ON DELETE CASCADE, FOREIGN KEY(library_id,workspace_id) REFERENCES libraries(id,workspace_id) ON DELETE CASCADE);
CREATE TABLE source_courses (source_id TEXT NOT NULL, course_id TEXT NOT NULL, workspace_id TEXT NOT NULL, PRIMARY KEY(source_id,course_id), FOREIGN KEY(source_id,workspace_id) REFERENCES sources(id,workspace_id) ON DELETE CASCADE, FOREIGN KEY(course_id,workspace_id) REFERENCES courses(id,workspace_id) ON DELETE CASCADE);
CREATE TABLE source_chunks (id TEXT PRIMARY KEY, source_id TEXT NOT NULL, workspace_id TEXT NOT NULL, text TEXT NOT NULL, page INTEGER, section TEXT, position INTEGER NOT NULL, FOREIGN KEY(source_id,workspace_id) REFERENCES sources(id,workspace_id) ON DELETE CASCADE);
CREATE INDEX chunks_workspace_source ON source_chunks(workspace_id,source_id);
CREATE VIRTUAL TABLE source_fts USING fts5(text, content='source_chunks', content_rowid='rowid', tokenize='unicode61');
CREATE TRIGGER chunks_insert AFTER INSERT ON source_chunks BEGIN INSERT INTO source_fts(rowid,text) VALUES(new.rowid,new.text); END;
CREATE TRIGGER chunks_delete AFTER DELETE ON source_chunks BEGIN INSERT INTO source_fts(source_fts,rowid,text) VALUES('delete',old.rowid,old.text); END;
CREATE TRIGGER chunks_update AFTER UPDATE ON source_chunks BEGIN INSERT INTO source_fts(source_fts,rowid,text) VALUES('delete',old.rowid,old.text); INSERT INTO source_fts(rowid,text) VALUES(new.rowid,new.text); END;
INSERT INTO libraries SELECT 'library-'||c.id,c.workspace_id,json_object('id','library-'||c.id,'workspaceId',c.workspace_id,'name',json_extract(c.payload,'$.name'),'createdAt',json_extract(c.payload,'$.createdAt')) FROM courses c WHERE EXISTS(SELECT 1 FROM library_notes n WHERE n.course_id=c.id);
INSERT INTO sources SELECT n.id,c.workspace_id,json_object('id',n.id,'workspaceId',c.workspace_id,'libraryIds',json_array('library-'||c.id),'courseIds',json_array(c.id),'title',json_extract(n.payload,'$.title'),'type','pasted','importedAt',json_extract(n.payload,'$.createdAt'),'pages',json_array(json_object('page',NULL,'text',json_extract(n.payload,'$.content'))),'tags',json_array('migrated')) FROM library_notes n JOIN courses c ON n.course_id=c.id;
INSERT INTO source_libraries SELECT n.id,'library-'||c.id,c.workspace_id FROM library_notes n JOIN courses c ON n.course_id=c.id;
INSERT INTO source_courses SELECT n.id,c.id,c.workspace_id FROM library_notes n JOIN courses c ON n.course_id=c.id;
INSERT INTO schema_migrations(version) VALUES(2);
